class GoalCreationTimeTest
{
    @Test
    void existingRecordsAndMalformedMetadataRemainReadable()
    {
        String legacy = "a,MINING,1000,2000,0,false;b,FISHING,100,3000,0,false";
        GoalTracker tracker = GoalTracker.decode(legacy);
        tracker.restoreCreationTimes("a,1700000000000;b,not-a-time;missing,1700000000000;bad");
        assertEquals(legacy, tracker.encode());
        assertEquals(1700000000000L, tracker.goals().get(0).createdAtEpochMillis);
        assertNull(tracker.goals().get(1).createdAtEpochMillis);
        GoalTracker noMetadata = GoalTracker.decode(legacy);
        noMetadata.restoreCreationTimes(null);
        assertNull(noMetadata.goals().get(0).createdAtEpochMillis);
        assertNull(noMetadata.goals().get(1).createdAtEpochMillis);
    }

    @Test
    void creationTimeSurvivesEditReloadAndIsRemovedWithGoal() throws Exception
    {
        Client client = mock(Client.class);
        ConfigManager config = mock(ConfigManager.class);
        Map<String, String> saved = new HashMap<>();
        when(config.getRSProfileKey()).thenReturn("character-a");
        when(config.getRSProfileConfiguration(eq(ActiveGoalsPlugin.CONFIG_GROUP), anyString()))
            .thenAnswer(call -> saved.get(call.getArgument(1)));
        doAnswer(call -> { saved.put(call.getArgument(1), call.getArgument(2)); return null; })
            .when(config).setRSProfileConfiguration(eq(ActiveGoalsPlugin.CONFIG_GROUP), anyString(), anyString());
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getSkillExperience(Skill.MINING)).thenReturn(1000);
        ActiveGoalsPlugin plugin = plugin(client, config);
        long before = System.currentTimeMillis();
        plugin.addIndividualGoal(Skill.MINING, 0, 2000);
        long after = System.currentTimeMillis();
        GoalTracker.Goal goal = plugin.individualGoals().get(0);
        assertNotNull(goal.createdAtEpochMillis);
        assertTrue(goal.createdAtEpochMillis >= before && goal.createdAtEpochMillis <= after);
        long created = goal.createdAtEpochMillis;
        String id = goal.id;
        assertEquals(6, saved.get("individualGoals").split(",", -1).length);
        plugin.editIndividualGoal(id, 0, 3000);
        assertEquals(created, goal.createdAtEpochMillis);

        ActiveGoalsPlugin restarted = plugin(client, config);
        GoalTracker.Goal restored = restarted.individualGoals().get(0);
        assertEquals(id, restored.id);
        assertEquals(created, restored.createdAtEpochMillis);
        restarted.removeIndividualGoal(id);
        assertTrue(restarted.individualGoals().isEmpty());
        assertFalse(saved.getOrDefault("goalCreationTimes", "").contains(id));
    }

    @Test
    void metadataIsIsolatedByProfile() throws Exception
    {
        Client client = mock(Client.class);
        ConfigManager config = mock(ConfigManager.class);
        AtomicReference<String> profile = new AtomicReference<>("a");
        Map<String, Map<String, String>> saved = new HashMap<>();
        when(config.getRSProfileKey()).thenAnswer(call -> profile.get());
        when(config.getRSProfileConfiguration(eq(ActiveGoalsPlugin.CONFIG_GROUP), anyString()))
            .thenAnswer(call -> saved.getOrDefault(profile.get(), Map.of()).get(call.getArgument(1)));
        doAnswer(call -> { saved.computeIfAbsent(profile.get(), key -> new HashMap<>())
            .put(call.getArgument(1), call.getArgument(2)); return null; })
            .when(config).setRSProfileConfiguration(eq(ActiveGoalsPlugin.CONFIG_GROUP), anyString(), anyString());
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getSkillExperience(Skill.MINING)).thenReturn(1000);
        ActiveGoalsPlugin a = plugin(client, config);
        a.addIndividualGoal(Skill.MINING, 0, 2000);
        String id = a.individualGoals().get(0).id;
        long created = a.individualGoals().get(0).createdAtEpochMillis;
        profile.set("b");
        saved.computeIfAbsent("b", key -> new HashMap<>()).put("individualGoals", id + ",MINING,1000,2000,0,false");
        ActiveGoalsPlugin b = plugin(client, config);
        assertNull(b.individualGoals().get(0).createdAtEpochMillis);
        profile.set("a");
        assertEquals(created, plugin(client, config).individualGoals().get(0).createdAtEpochMillis);
    }

    @Test
    void completedGoalKeepsCreationTimeUntilAutomaticRemoval() throws Exception
    {
        Client client = mock(Client.class);
        ConfigManager config = mock(ConfigManager.class);
        Map<String, String> saved = new HashMap<>();
        when(config.getRSProfileKey()).thenReturn("character-a");
        when(config.getRSProfileConfiguration(eq(ActiveGoalsPlugin.CONFIG_GROUP), anyString()))
            .thenAnswer(call -> saved.get(call.getArgument(1)));
        doAnswer(call -> { saved.put(call.getArgument(1), call.getArgument(2)); return null; })
            .when(config).setRSProfileConfiguration(eq(ActiveGoalsPlugin.CONFIG_GROUP), anyString(), anyString());
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getSkillExperience(Skill.MINING)).thenReturn(1000);
        ActiveGoalsPlugin plugin = plugin(client, config);
        plugin.addIndividualGoal(Skill.MINING, 0, 2000);
        GoalTracker.Goal goal = plugin.individualGoals().get(0);
        goal.completed = true;
        goal.completedAtNanos = System.nanoTime() - 61_000_000_000L;
        assertTrue(saved.get("goalCreationTimes").contains(goal.id));
        plugin.onGameTick(new GameTick());
        assertTrue(plugin.individualGoals().isEmpty());
        assertFalse(saved.getOrDefault("goalCreationTimes", "").contains(goal.id));
    }

    @Test
    void expandedCardShowsKnownAndUnknownCreationTimes() throws Exception
    {
        ActiveGoalsPlugin plugin = mock(ActiveGoalsPlugin.class);
        Client client = mock(Client.class);
        GoalTracker tracker = new GoalTracker();
        GoalTracker.Goal unknown = tracker.add(Skill.MINING, 1000, 2000, 1);
        GoalTracker.Goal known = tracker.add(Skill.MINING, 1000, 3000, 1);
        known.createdAtEpochMillis = 1_700_000_000_000L;
        when(plugin.individualGoals()).thenReturn(tracker.goals());
        when(plugin.getClient()).thenReturn(client);
        when(plugin.goalDataReady()).thenReturn(true);
        when(plugin.goalClockNanos()).thenReturn(2L);
        when(plugin.getGoalCardExpansionSeconds()).thenReturn(300);
        when(client.getSkillExperience(Skill.MINING)).thenReturn(1500);
        doAnswer(call -> { call.<Runnable>getArgument(0).run(); return null; })
            .when(plugin).runOnClientThread(any(Runnable.class));
        ActiveGoalsPanel panel = new ActiveGoalsPanel(plugin, mock(SkillIconManager.class));
        String expected = DateTimeFormatter.ofPattern("d MMM uuuu, h:mm a", Locale.ENGLISH)
            .withZone(ZoneId.systemDefault()).format(Instant.ofEpochMilli(known.createdAtEpochMillis));
        try
        {
            SwingUtilities.invokeAndWait(panel::start);
            SwingUtilities.invokeAndWait(() -> {
                assertTrue(hasLabel(panel, "Created:"));
                assertTrue(hasLabel(panel, expected));
                assertTrue(hasLabel(panel, "Unknown"));
            });
        }
        finally { SwingUtilities.invokeAndWait(panel::stop); }
    }

    private static ActiveGoalsPlugin plugin(Client client, ConfigManager config) throws Exception
    {
        ActiveGoalsPlugin plugin = new ActiveGoalsPlugin();
        inject(plugin, "client", client);
        inject(plugin, "configManager", config);
        inject(plugin, "activeGoalsPanel", mock(ActiveGoalsPanel.class));
        inject(plugin, "xpBaselineTicks", 1);
        plugin.onGameTick(new GameTick());
        return plugin;
    }

    private static void inject(Object target, String name, Object value) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static boolean hasLabel(Container container, String text)
    {
        for (Component child : container.getComponents())
        {
            if (child instanceof JLabel && text.equals(((JLabel) child).getText())) return true;
            if (child instanceof Container && hasLabel((Container) child, text)) return true;
        }
        return false;
    }
}

package com.activegoals;

import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class GoalOrderingTest
{
    @Test
    void activityMovesIncompleteGoalsTogetherAndKeepsOtherCardsInOrder()
    {
        GoalTracker tracker = GoalTracker.decode("a,MINING,0,1000,0,false;done,MINING,0,1000,0,true;"
            + "b,FISHING,0,1000,0,false;bad,!CORRUPTED;c,MINING,0,1000,0,false");
        tracker.recordTrainingGain(Skill.MINING, 1, 5);
        assertEquals("a;c;done;b;bad", ids(tracker));
        assertEquals(tracker.encode(), GoalTracker.decode(tracker.encode()).encode());
        tracker.recordTrainingGain(Skill.FISHING, 2, 5);
        assertEquals("b;a;c;done;bad", ids(tracker));
        tracker.recordTrainingGain(Skill.MINING, 3, 5);
        assertEquals("b;a;c;done;bad", ids(tracker));
        tracker.recordTrainingGain(Skill.MINING, 5_000_000_003L, 5);
        assertEquals("a;c;b;done;bad", ids(tracker));
    }

    @Test
    void noGoalDoesNotStartActivityAndResetStartsNewActivity()
    {
        GoalTracker tracker = new GoalTracker();
        tracker.recordTrainingGain(Skill.MINING, 1, 5);
        GoalTracker.Goal mining = tracker.add(Skill.MINING, 0, 1000, 2);
        GoalTracker.Goal fishing = tracker.add(Skill.FISHING, 0, 1000, 2);
        tracker.recordTrainingGain(Skill.MINING, 3, 5);
        assertEquals(mining, tracker.goals().get(0));
        tracker.recordTrainingGain(Skill.FISHING, 4, 5);
        assertEquals(fishing, tracker.goals().get(0));
        tracker.clearTrainingActivity();
        tracker.recordTrainingGain(Skill.MINING, 5, 5);
        assertEquals(mining, tracker.goals().get(0));
    }

    @Test
    void completedOrDeletedLastGoalDoesNotKeepActivityForNewGoal()
    {
        GoalTracker tracker = new GoalTracker();
        tracker.add(Skill.MINING, 0, 100, 1);
        tracker.recordTrainingGain(Skill.MINING, 2, 5);
        tracker.gain(Skill.MINING, 100, 100, 2);
        GoalTracker.Goal newMining = tracker.add(Skill.MINING, 100, 200, 3);
        tracker.add(Skill.FISHING, 0, 100, 3);
        tracker.recordTrainingGain(Skill.MINING, 4, 5);
        assertEquals(newMining, tracker.goals().get(0));
        tracker.remove(newMining.id);
        GoalTracker.Goal again = tracker.add(Skill.MINING, 100, 200, 5);
        tracker.add(Skill.FISHING, 0, 200, 5);
        tracker.recordTrainingGain(Skill.MINING, 6, 5);
        assertEquals(again, tracker.goals().get(0));
    }

    @Test
    void completingGoalIsNotMovedWhenAnotherGoalRemains()
    {
        GoalTracker tracker = GoalTracker.decode("other,FISHING,0,1000,0,false;"
            + "short,MINING,0,100,0,false;long,MINING,0,1000,0,false");
        tracker.gain(Skill.MINING, 100, 100, 1);
        tracker.recordTrainingGain(Skill.MINING, 1, 5);
        assertEquals("long;other;short", ids(tracker));
    }
    @Test
    void reconciliationCompletingLastGoalDoesNotKeepOldActivity()
    {
        GoalTracker tracker = new GoalTracker();
        GoalTracker.Goal previous = tracker.add(Skill.MINING, 0, 100, 1);
        tracker.recordTrainingGain(Skill.MINING, 2, 5);
        previous.completed = true; // Login or world-hop reconciliation.
        GoalTracker.Goal next = tracker.add(Skill.MINING, 100, 200, 3);
        tracker.add(Skill.FISHING, 0, 200, 3);
        tracker.recordTrainingGain(Skill.MINING, 4, 5);
        assertEquals(next, tracker.goals().get(0));
    }
    @Test
    void manuallyCollapsedCardMovesWithoutOpeningAndSurvivesReload()
    {
        GoalTracker tracker = GoalTracker.decode("other,FISHING,0,1000,0,false;mine,MINING,0,1000,0,false");
        tracker.restoreManualCollapses("mine");
        assertFalse(tracker.gain(Skill.MINING, 100, 100, 1));
        tracker.recordTrainingGain(Skill.MINING, 1, 5);
        assertEquals("mine;other", ids(tracker));
        GoalTracker.Goal mining = tracker.goals().get(0);
        assertTrue(mining.manuallyCollapsed);
        assertEquals(0, mining.expandedAtNanos);
        GoalTracker restored = GoalTracker.decode(tracker.encode());
        restored.restoreManualCollapses(tracker.encodeManualCollapses());
        assertEquals("mine;other", ids(restored));
        assertTrue(restored.goals().get(0).manuallyCollapsed);
    }

    @Test
    void completedCollapsedGoalOpensWhileRemainingGoalMovesAndPersists()
    {
        GoalTracker tracker = GoalTracker.decode("other,FISHING,0,1000,0,false;"
            + "short,MINING,0,100,0,false;long,MINING,0,1000,0,false");
        tracker.restoreManualCollapses("short;long");
        assertTrue(tracker.gain(Skill.MINING, 100, 100, 1));
        tracker.recordTrainingGain(Skill.MINING, 1, 5);
        assertEquals("long;other;short", ids(tracker));
        assertEquals("long", tracker.encodeManualCollapses());
        assertTrue(tracker.goals().get(2).completed);
        assertFalse(tracker.goals().get(2).manuallyCollapsed);
        assertEquals(1, tracker.goals().get(2).expandedAtNanos);
        GoalTracker restored = GoalTracker.decode(tracker.encode());
        restored.restoreManualCollapses(tracker.encodeManualCollapses());
        assertEquals("long;other;short", ids(restored));
        assertTrue(restored.goals().get(0).manuallyCollapsed);
    }
    private static String ids(GoalTracker tracker)
    {
        StringBuilder result = new StringBuilder();
        for (GoalTracker.Goal goal : tracker.goals())
        {
            if (result.length() > 0) result.append(';');
            result.append(goal.id);
        }
        return result.toString();
    }
}

package com.activegoals;

import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class GoalTrackerTest
{
    @Test
    void manualCollapseSurvivesRoundTripAndOnlyCompletionReopensIt()
    {
        GoalTracker tracker = new GoalTracker();
        GoalTracker.Goal first = tracker.add(Skill.MINING, 1000, 1200, 1);
        GoalTracker.Goal second = tracker.add(Skill.MINING, 1000, 2000, 1);
        first.manuallyCollapsed = true;
        first.expandedAtNanos = 0;
        String goals = tracker.encode();
        GoalTracker restored = GoalTracker.decode(goals);
        restored.restoreManualCollapses(first.id + ";unknown;invalid");
        GoalTracker.Goal restoredFirst = restored.goals().get(1);
        GoalTracker.Goal restoredSecond = restored.goals().get(0);
        assertEquals(goals, restored.encode());
        assertEquals(first.id, restored.encodeManualCollapses());
        assertFalse(restored.gain(Skill.MINING, 1100, 100, 2));
        assertTrue(restoredFirst.manuallyCollapsed);
        assertEquals(0, restoredFirst.expandedAtNanos);
        assertEquals(100, restoredFirst.sessionXp);
        assertEquals(100, restoredFirst.rateXp);
        assertEquals(100, restoredFirst.samples.getFirst());
        assertFalse(restoredSecond.manuallyCollapsed);
        assertEquals(2, restoredSecond.expandedAtNanos);
        assertTrue(restored.gain(Skill.MINING, 1200, 100, 3));
        assertTrue(restoredFirst.completed);
        assertFalse(restoredFirst.manuallyCollapsed);
        assertEquals(3, restoredFirst.expandedAtNanos);
        assertEquals("", restored.encodeManualCollapses());
    }

    @Test
    void autoCollapseResetsRateAndSamplesButPreservesSessionXp()
    {
        GoalTracker tracker = new GoalTracker();
        GoalTracker.Goal goal = tracker.add(Skill.MINING, 1000, 5000, 1);
        tracker.gain(Skill.MINING, 1100, 100, 2);
        goal.expireExpansion(300_000_000_002L, 300);
        assertEquals(100, goal.sessionXp);
        assertEquals(0, goal.rateXp);
        assertEquals(0, goal.ratePeriodStartNanos);
        assertTrue(goal.samples.isEmpty());
        tracker.gain(Skill.MINING, 1150, 50, 300_000_000_003L);
        assertEquals(150, goal.sessionXp);
        assertEquals(50, goal.rateXp);
        assertEquals(50, goal.samples.getFirst());
    }
    @Test
    void decodeKeepsValidGoalsAndPersistsUnreadablePlaceholders()
    {
        String data = "first,MINING,100,2000,0,false;bad;broken,UNKNOWN,0,500,0,false;"
            + "invalid,FISHING,nope,500,0,false;last,FISHING,10,600,0,false";
        GoalTracker restored = GoalTracker.decode(data);
        assertEquals(5, restored.goals().size());
        assertEquals("first", restored.goals().get(0).id);
        assertNull(restored.goals().get(1).skill);
        assertNull(restored.goals().get(2).skill);
        assertNull(restored.goals().get(3).skill);
        assertEquals("last", restored.goals().get(4).id);
        String encoded = restored.encode();
        GoalTracker reloaded = GoalTracker.decode(encoded);
        assertEquals(encoded, reloaded.encode());
        reloaded.remove(reloaded.goals().get(1).id);
        assertEquals(4, GoalTracker.decode(reloaded.encode()).goals().size());
    }

    @Test
    void duplicateIdsAreRepairedWithoutDiscardingGoals()
    {
        GoalTracker tracker = GoalTracker.decode("same,MINING,2000,2000,0,false;same,FISHING,10,600,0,false");
        assertEquals(2, tracker.goals().size());
        assertNotEquals(tracker.goals().get(0).id, tracker.goals().get(1).id);
        tracker.remove(tracker.goals().get(0).id);
        assertEquals(Skill.FISHING, tracker.goals().get(0).skill);
    }
    @Test
    void startingLevelStaysFixedAfterLevelingAndReload()
    {
        GoalTracker tracker = new GoalTracker();
        GoalTracker.Goal goal = tracker.add(Skill.MINING, 83, 5000, 1);
        tracker.gain(Skill.MINING, 1000, 917, 2);
        assertEquals(2, goal.startingLevel());
        assertEquals(2, GoalTracker.decode(tracker.encode()).goals().get(0).startingLevel());
    }
    @Test
    void identicalTargetsCreateIndependentGoals()
    {
        GoalTracker tracker = new GoalTracker();
        GoalTracker.Goal first = tracker.add(Skill.MINING, 1000, 2000, 0);
        GoalTracker.Goal second = tracker.add(Skill.MINING, 1500, 2000, 0);
        tracker.gain(Skill.MINING, 1600, 100, 1);
        assertEquals(0.6, first.progress(1600), 0.00001);
        assertEquals(0.2, second.progress(1600), 0.00001);
        assertEquals(100, first.sessionXp());
        assertEquals(100, second.sessionXp());
        tracker.remove(first.id());
        assertEquals(1, tracker.goals().size());
        assertEquals(second.id(), tracker.goals().get(0).id());
    }

    @Test
    void oneCompletedGoalDoesNotStopAnotherGoal()
    {
        GoalTracker tracker = new GoalTracker();
        GoalTracker.Goal shorter = tracker.add(Skill.MINING, 1000, 1100, 0);
        GoalTracker.Goal longer = tracker.add(Skill.MINING, 1000, 1500, 0);
